use hec_native_ic::{fp::Fp,poly::Poly,jac::{Curve,Div}};
use crate::{models::Model,legacy_pic::{PlaneQuartic,PicClass,Gen}};
#[derive(Clone,Copy,Debug,PartialEq,Eq)]struct E([Poly;2]);
impl E{fn zero()->Self{Self([Poly::zero();2])}fn one()->Self{Self([Poly::one(),Poly::zero()])}fn constant(p:Poly)->Self{Self([p,Poly::zero()])}fn add(self,b:Self,u:&Poly,f:&Fp)->Self{Self([self.0[0].add(&b.0[0],f).rem(u,f),self.0[1].add(&b.0[1],f).rem(u,f)])}fn neg(self,f:&Fp)->Self{Self([self.0[0].neg(f),self.0[1].neg(f)])}fn mul(self,b:Self,c:&[Poly;2],u:&Poly,f:&Fp)->Self{let rr=self.0[1].mulmod(&b.0[1],u,f);Self([self.0[0].mulmod(&b.0[0],u,f).sub(&rr.mulmod(&c[0],u,f),f).rem(u,f),self.0[0].mulmod(&b.0[1],u,f).add(&self.0[1].mulmod(&b.0[0],u,f),f).sub(&rr.mulmod(&c[1],u,f),f).rem(u,f)])}fn pow(self,n:usize,c:&[Poly;2],u:&Poly,f:&Fp)->Self{(0..n).fold(Self::one(),|a,_|a.mul(self,c,u,f))}}
fn unit(p:&Poly,u:&Poly,f:&Fp)->Option<Poly>{let(g,i,_)=Poly::xgcd(p,u,f);if g==Poly::one(){Some(i.rem(u,f))}else{None}}
fn ev(cs:&[u64],t:&Poly,u:&Poly,f:&Fp)->Poly{cs.iter().rev().fold(Poly::zero(),|a,&c|a.mulmod(t,u,f).add(&Poly::constant(c),f).rem(u,f))}
fn effective(source:&Curve,d:&Div,model:&Model,pc:&PlaneQuartic)->Option<Gen>{let f=&source.fp;let u=&d.u;if u.deg()!=3||Poly::gcd(u,&u.deriv(f),f).deg()!=0{return None;}let x=Poly::from_coeffs(&[0,1]);let den=Poly::from_coeffs(&model.d).rem(u,f);let t=Poly::from_coeffs(&model.n).mulmod(&unit(&den,u,f)?,u,f);let a=ev(&model.ds[3],&t,u,f);let ia=unit(&a,u,f)?;let delta1=ev(&model.ds[1],&t,u,f).scale(f.mul(8,f.sqrt(model.alpha).unwrap()),f);unit(&delta1,u,f)?;unit(&ev(&model.disc,&t,u,f),u,f)?;let delta2=ev(&model.ds[2],&t,u,f);let sum=delta2.mulmod(&ia,u,f).scale(f.neg(f.inv(2)),f);let kappa=delta1.mulmod(&ia,u,f).scale(f.inv(8),f);
let gp=x.mulmod(&x,u,f).scale(3,f).sub(&t.mulmod(&x,u,f).scale(2,f),f).add(&Poly::constant(model.n[1]).sub(&t.scale(model.d[1],f),f),f).rem(u,f);let lambda=d.v.mulmod(&unit(&gp,u,f)?,u,f);let il=unit(&lambda,u,f)?;let c=[lambda.mulmod(&lambda,u,f).scale(2,f).sub(&sum,f).sub(&kappa.mulmod(&il,u,f).scale(2,f),f).rem(u,f),lambda.scale(f.neg(2),f)];let discr=c[1].mulmod(&c[1],u,f).sub(&c[0].scale(4,f),f).rem(u,f);unit(&discr,u,f)?;
let rho=E([Poly::zero(),Poly::one()]);let ts=E::constant(t);let mut q=E::zero();for(k,coeffs)in [&model.ds[0],&model.ds[1],&model.ds[2],&vec![],&model.ds[3]].iter().enumerate(){let mut cv=ev(coeffs,&t,u,f);if k==1{cv=cv.scale(f.neg(f.mul(8,f.sqrt(model.alpha).unwrap())),f);}q=q.add(E::constant(cv).mul(rho.pow(k,&c,u,f),&c,u,f),u,f);}assert_eq!(q,E::zero(),"source incidence quadratic does not divide scalar quartic");
let coordinates=model.sections.iter().map(|h|h.iter().fold(E::zero(),|s,&(i,j,v)|{s.add(ts.pow(i,&c,u,f).mul(rho.pow(j,&c,u,f),&c,u,f).mul(E::constant(Poly::constant(v)),&c,u,f),u,f)})).collect::<Vec<_>>();let mut equation=E::zero();for((i,j,k),&coeff)in crate::legacy_pic::mons_of_degree(4).iter().zip(model.coeff.iter()){let term=coordinates[0].pow(*i as usize,&c,u,f).mul(coordinates[1].pow(*j as usize,&c,u,f),&c,u,f).mul(coordinates[2].pow(*k as usize,&c,u,f),&c,u,f).mul(E::constant(Poly::constant(coeff)),&c,u,f);equation=equation.add(term,u,f);}assert_eq!(equation,E::zero(),"canonical curve equation failed on image algebra");
// At least one homogeneous coordinate must be a unit across all six points.
if !coordinates.iter().any(|z|{let norm=z.0[0].mulmod(&z.0[0],u,f).sub(&z.0[0].mulmod(&z.0[1],u,f).mulmod(&c[1],u,f),f).add(&z.0[1].mulmod(&z.0[1],u,f).mulmod(&c[0],u,f),f).rem(u,f);unit(&norm,u,f).is_some()}){return None;}
let cols=pc.std_monomials(3).iter().map(|&(i,j,k)|coordinates[0].pow(i as usize,&c,u,f).mul(coordinates[1].pow(j as usize,&c,u,f),&c,u,f).mul(coordinates[2].pow(k as usize,&c,u,f),&c,u,f)).collect::<Vec<_>>();let rows=(0..6).map(|r|cols.iter().map(|v|v.0[r/3].c[r%3]).collect::<Vec<_>>()).collect::<Vec<_>>();let kernel=pc.linear_kernel(rows.clone(),10);if kernel.len()!=4{return None;}for v in &kernel{for r in &rows{assert_eq!(r.iter().zip(v).fold(0,|s,(&a,&b)|f.add(s,f.mul(a,b))),0);}}Some(Gen{k:3,rows:kernel})}
#[derive(Debug)]pub struct Receipt{pub aux_scalar:u64,pub rejected:usize,pub class:PicClass}
pub fn transport(source:&Curve,input:&Div,aux_base:&Div,model:&Model,pc:&PlaneQuartic,start:u64)->Option<Receipt>{if !source.is_valid(input){return None;}if source.is_zero(input){return Some(Receipt{aux_scalar:0,rejected:0,class:pc.zero()});}for j in start..start+512{let a=source.mul(aux_base,j);let b=source.add(input,&a);assert_eq!(source.add(&b,&source.neg(&a)),*input);let Some(ga)=effective(source,&a,model,pc)else{continue;};let Some(gb)=effective(source,&b,model,pc)else{continue;};let aa=pc.reduce_deg6(&ga);let bb=pc.reduce_deg6(&gb);let class=pc.sub(&bb,&aa);return Some(Receipt{aux_scalar:j,rejected:(j-start)as usize,class});}None}
